1: // Fixture-owned oracles for the batched-queue benchmark harness.
2: //
3: // Oracles read hidden proof files under .bench/proof/ and run deterministic
4: // re-verification commands in the fixture directory. They do not decide
5: // correctness from the final assistant message alone.
6: 
7: import { createHash } from "node:crypto";
8: import { exec } from "node:child_process";
9: import { readdirSync, readFileSync } from "node:fs";
10: import { join, relative } from "node:path";
11: import type { FixtureExpectations, OracleContext, OracleResult } from "./types.ts";
12: 
13: export interface ProofSpec {
14: 	/** Scenario family for runbook reporting. */
15: 	family: string;
16: 	/** Substrings that must appear in the final text or any bash/batch output. */
17: 	expectedSubstrings?: string[];
18: 	/** Bash command to re-run in the fixture directory (side-effect bounded). */
19: 	reverifyCommand?: string;
20: 	/** Expected exit code for reverifyCommand; defaults to 0. */
21: 	expectedExitCode?: number;
22: 	/** Substrings that must appear in the reverify command output. */
23: 	reverifyOutputContains?: string[];
24: 	/** Substrings that must not appear in any bash/batch output. */
25: 	forbiddenOutput?: string[];
26: 	/** Whether the fixture must remain byte-for-byte unchanged (ignoring .bench/proof). */
27: 	noMutation?: boolean;
28: }
29: 
30: function normalize(text: string): string {
31: 	return text.toLowerCase().replace(/[\s`*_]+/g, "");
32: }
33: 
34: function contains(text: string, needle: string): boolean {
35: 	return normalize(text).includes(normalize(needle));
36: }
37: 
38: function anyContains(outputs: readonly string[], needle: string): boolean {
39: 	return outputs.some((o) => contains(o, needle));
40: }
41: 
42: export function reverify(
43: 	fixtureDir: string,
44: 	command: string,
45: 	timeoutMs = 30000,
46: ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
47: 	return new Promise((resolve, reject) => {
48: 		const child = exec(
49: 			command,
50: 			{ cwd: fixtureDir, timeout: timeoutMs, killSignal: "SIGKILL" },
51: 			(error, stdout, stderr) => {
52: 				if (error && error.killed) {
53: 					reject(new Error(`reverify timed out: ${command}`));
54: 					return;
55: 				}
56: 				resolve({
57: 					exitCode: error?.code ? Number(error.code) : 0,
58: 					stdout: stdout.toString(),
59: 					stderr: stderr.toString(),
60: 				});
61: 			},
62: 		);
63: 		// Defensive fallback in case the timeout option is ignored.
64: 		setTimeout(() => child.kill("SIGKILL"), timeoutMs + 1000);
65: 	});
66: }
67: 
68: function shouldIgnore(entry: string, ignored: readonly string[]): boolean {
69: 	return ignored.some((name) => entry === name || entry.startsWith(`${name}/`));
70: }
71: 
72: export function computeDigest(
73: 	fixtureDir: string,
74: 	ignoredDirs: readonly string[] = [".bench/proof"],
75: ): string {
76: 	const hash = createHash("sha256");
77: 	function walk(dir: string) {
78: 		const entries = readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
79: 			a.name.localeCompare(b.name),
80: 		);
81: 		for (const entry of entries) {
82: 			const full = join(dir, entry.name);
83: 			const rel = relative(fixtureDir, full);
84: 			if (shouldIgnore(rel, ignoredDirs)) continue;
85: 			if (entry.isDirectory()) {
86: 				walk(full);
87: 			} else if (entry.isFile()) {
88: 				hash.update(rel);
89: 				hash.update(readFileSync(full));
90: 			}
91: 		}
92: 	}
93: 	walk(fixtureDir);
94: 	return hash.digest("hex");
95: }
96: 
97: export async function defaultOracle(ctx: OracleContext): Promise<OracleResult> {
98: 	const proof = ctx.expected.proof as ProofSpec | undefined;
99: 	if (!proof) {
100: 		return { passed: false, checks: { proof: false }, note: "missing proof spec" };
101: 	}
102: 
103: 	const checks: Record<string, boolean> = {};
104: 	const outputs = [ctx.parsed.finalAssistantText, ...ctx.parsed.bashOutputs];
105: 	let note = "";
106: 
107: 	if (proof.expectedSubstrings) {
108: 		for (const sub of proof.expectedSubstrings) {
109: 			checks[`expected:${sub}`] = outputs.some((o) => contains(o, sub));
110: 		}
111: 	}
112: 
113: 	if (proof.forbiddenOutput) {
114: 		for (const sub of proof.forbiddenOutput) {
115: 			checks[`forbidden:${sub}`] = !ctx.parsed.bashOutputs.some((o) =>
116: 				contains(o, sub),
117: 			);
118: 		}
119: 	}
120: 
121: 	if (proof.reverifyCommand) {
122: 		const { exitCode, stdout, stderr } = await ctx.reverify(
123: 			proof.reverifyCommand,
124: 			30000,
125: 		);
126: 		const expectedExit = proof.expectedExitCode ?? 0;
127: 		checks["reverify:exitCode"] = exitCode === expectedExit;
128: 
129: 		const output = stdout + stderr;
130: 		const required = proof.reverifyOutputContains ?? proof.expectedSubstrings ?? [];
131: 		for (const sub of required) {
132: 			checks[`reverify:${sub}`] = contains(output, sub);
133: 		}
134: 	}
135: 
136: 	if (proof.noMutation) {
137: 		const expectedDigest = ctx.readFixtureFile(".bench/proof/.digest");
138: 		const actualDigest = computeDigest(ctx.fixtureDir, [".bench/proof"]);
139: 		checks["noMutation"] = expectedDigest === actualDigest;
140: 		if (!checks["noMutation"]) {
141: 			note += "fixture mutated; ";
142: 		}
143: 	}
144: 
145: 	const passed = Object.values(checks).every(Boolean);
146: 	return { passed, checks, note: note || undefined };
147: }
148: 
