1: // Aggregator + Markdown report generator for benchmark runs.
2: //
3: // Reads runs.json (array of RunSummary) and manifest.json from a results
4: // directory, computes per (scenario, condition) statistics, derived reductions
5: // relative to the native baseline, and writes aggregate.json + REPORT.md.
6: //
7: // Usage: bun benchmarks/harness/aggregate.ts <results-dir>
8: 
9: import { readFileSync, writeFileSync } from "node:fs";
10: import { join } from "node:path";
11: import type { ConditionId, Manifest, RunSummary } from "./types.ts";
12: 
13: function median(values: number[]): number {
14: 	if (values.length === 0) return 0;
15: 	const sorted = [...values].sort((a, b) => a - b);
16: 	const mid = Math.floor(sorted.length / 2);
17: 	return sorted.length % 2 === 0
18: 		? (sorted[mid - 1] + sorted[mid]) / 2
19: 		: sorted[mid];
20: }
21: 
22: function percentile(values: number[], p: number): number {
23: 	if (values.length === 0) return 0;
24: 	const sorted = [...values].sort((a, b) => a - b);
25: 	const idx = Math.min(
26: 		sorted.length - 1,
27: 		Math.max(0, Math.ceil((p / 100) * sorted.length) - 1),
28: 	);
29: 	return sorted[idx];
30: }
31: 
32: function mean(values: number[]): number {
33: 	if (values.length === 0) return 0;
34: 	return values.reduce((a, b) => a + b, 0) / values.length;
35: }
36: 
37: interface CellStats {
38: 	scenario: string;
39: 	condition: ConditionId;
40: 	n: number;
41: 	successRate: number;
42: 	medianTurns: number;
43: 	medianToolCalls: number;
44: 	medianActions: number;
45: 	medianActionCompression: number;
46: 	medianCost: number;
47: 	medianPlannerCost: number;
48: 	medianTotalCost: number;
49: 	medianElapsedMs: number;
50: 	p95ElapsedMs: number;
51: 	medianInputTokens: number;
52: 	medianOutputTokens: number;
53: 	medianResultBytes: number;
54: 	meanBatchCalls: number;
55: 	haltedBatches: number;
56: 	costComplete: boolean;
57: }
58: 
59: function totalCostUsd(r: RunSummary): number {
60: 	return r.usage.costUsd + (r.plannerUsage?.costUsd ?? 0);
61: }
62: 
63: function computeCell(rows: RunSummary[]): CellStats {
64: 	const driverCost = median(rows.map((r) => r.usage.costUsd));
65: 	const plannerCost = median(rows.map((r) => r.plannerUsage?.costUsd ?? 0));
66: 	return {
67: 		scenario: rows[0].scenario,
68: 		condition: rows[0].condition,
69: 		n: rows.length,
70: 		successRate: mean(rows.map((r) => (r.verificationPassed ? 1 : 0))),
71: 		medianTurns: median(rows.map((r) => r.modelTurns)),
72: 		medianToolCalls: median(rows.map((r) => r.toolCalls)),
73: 		medianActions: median(rows.map((r) => r.actionsCompleted)),
74: 		medianActionCompression: median(rows.map((r) => r.actionCompression)),
75: 		medianCost: driverCost,
76: 		medianPlannerCost: plannerCost,
77: 		medianTotalCost: driverCost + plannerCost,
78: 		medianElapsedMs: median(rows.map((r) => r.elapsedMs)),
79: 		p95ElapsedMs: percentile(
80: 			rows.map((r) => r.elapsedMs),
81: 			95,
